from cfg.parser import parse


def test_basic():
    assert parse("[a]\nx = 1\n") == {"": {}, "a": {"x": "1"}}


def test_inline_comments():
    assert parse("[a]\nx = 1 # c\ny = 2 ; c\n") == {"": {}, "a": {"x": "1", "y": "2"}}


def test_quoted_values_protect_specials():
    assert parse('[a]\nx = "v # a ; b = c"\n') == {"": {}, "a": {"x": "v # a ; b = c"}}


def test_value_with_equals():
    assert parse("[a]\nx = a=b\n") == {"": {}, "a": {"x": "a=b"}}


def test_repeated_key_last_wins():
    assert parse("[a]\nx = 1\nx = 2\n") == {"": {}, "a": {"x": "2"}}


def test_keys_lowercased():
    assert parse("[a]\nFoo = 1\nFOO = 2\n") == {"": {}, "a": {"foo": "2"}}

